	@ParameterizedTest
	@MethodSource("codingPreferences")
	void browserStreamRespectsCodingQualitiesAndExclusions(String acceptEncoding, String expected) throws Exception {
		try (Fixture fixture = new Fixture()) {
			MockHttpServletResponse response = fixture.execute(QUERY, V2 + "," + V1, acceptEncoding);
			assertThat(response.getHeader("Content-Encoding")).isEqualTo(expected);
			assertThat(records(response).getLast().path("type").asText()).isEqualTo("end");
			assertThat(rows(records(response))).hasSize(4);
			if ("zstd".equals(expected)) {
				byte[] frame = response.getContentAsByteArray();
				assertThat(frame[4] & 32).isZero();
				int descriptor = frame[5] & 255;
				long base = 1L << (10 + (descriptor >> 3));
				assertThat(base + base / 8 * (descriptor & 7)).isLessThanOrEqualTo(8 * 1024 * 1024);
			}
		}
	}

