	@Test
	@ResourceLock(Resources.SYSTEM_PROPERTIES)
	void unavailableOptionalCodingFallsBackBeforeResponseCommit() throws Exception {
		String old = System.getProperty(RioCompression.DISABLED_ENCODINGS_PROPERTY);
		System.setProperty(RioCompression.DISABLED_ENCODINGS_PROPERTY, "zstd,br");
		try (Fixture fixture = new Fixture()) {
			MockHttpServletResponse response = fixture.execute(QUERY, V2 + "," + V1,
					"zstd;q=1,br;q=0.9,gzip;q=0.8,deflate;q=0");
			assertThat(response.getHeader("Content-Encoding")).isEqualTo("gzip");
			assertThat(rows(records(response))).hasSize(4);
		} finally {
			if (old == null) {
				System.clearProperty(RioCompression.DISABLED_ENCODINGS_PROPERTY);
			} else {
				System.setProperty(RioCompression.DISABLED_ENCODINGS_PROPERTY, old);
			}
		}
	}

