	private static List<JsonNode> records(MockHttpServletResponse response) throws Exception {
		return decoded(response).lines().filter(line -> !line.isBlank()).map(JSON::readTree).toList();
	}

	private static String decoded(MockHttpServletResponse response) throws Exception {
		InputStream source = new ByteArrayInputStream(response.getContentAsByteArray());
		String encoding = response.getHeader("Content-Encoding");
		if (encoding != null) {
			RioCompression codec = Stream.of(RioCompression.values())
					.filter(value -> value.contentEncoding().equals(encoding))
					.findFirst()
					.orElseThrow();
			source = codec.decompress(source);
		}
		try (InputStream decoded = source) {
			return new String(decoded.readAllBytes(), StandardCharsets.UTF_8);
		}
	}

	private static List<JsonNode> rows(List<JsonNode> records) {
		List<JsonNode> rows = new ArrayList<>();
		for (JsonNode record : records) {
			if ("rows".equals(record.path("type").asText())) {
				record.path("values").forEach(rows::add);
			}
		}
		return rows;
	}

